// src/pages/Stock.jsx
import { useState, useEffect } from 'react';
import api, { fmtGHS, fmtDate } from '../utils/api';

export default function StockPage() {
  const [stock,     setStock]     = useState([]);
  const [locations, setLocations] = useState([]);
  const [search,    setSearch]    = useState('');
  const [loading,   setLoading]   = useState(true);
  const [showForm,  setShowForm]  = useState(false);
  const [saving,    setSaving]    = useState(false);

  const { register, handleSubmit, reset } = useForm({
    defaultValues: { item_type: 'SPARE_PART', unit: 'pcs', opening_qty: 0, unit_price: 0, reorder_level: 0 }
  });

  const loadData = () => {
    setLoading(true);
    Promise.all([
      api.get('/inventory/closing-stock/'),
      api.get('/inventory/locations/')
    ]).then(([s, l]) => {
      setStock(s.data.results || s.data);
      setLocations(l.data.results || l.data);
    }).catch(() => {}).finally(() => setLoading(false));
  };

  useEffect(() => { loadData(); }, []);

  const onSubmit = async (data) => {
    setSaving(true);
    try {
      const payload = {
        name: data.name,
        item_type: data.item_type,
        unit: data.unit,
        description: data.description,
        reorder_level: parseFloat(data.reorder_level || 0),
      };
      if (parseFloat(data.opening_qty) > 0) {
        payload.opening_qty = parseFloat(data.opening_qty);
        payload.unit_price = parseFloat(data.unit_price);
        payload.location_id = data.location_id;
      }
      await api.post('/inventory/items/', payload);
      toast.success('Item created successfully.');
      reset();
      setShowForm(false);
      loadData();
    } catch (e) {
      toast.error(e.response?.data?.detail || JSON.stringify(e.response?.data) || 'Failed to create item.');
    } finally {
      setSaving(false);
    }
  };

  const filtered = stock.filter(s =>
    s.item_name?.toLowerCase().includes(search.toLowerCase()) ||
    s.item_code?.toLowerCase().includes(search.toLowerCase()) ||
    s.category?.toLowerCase().includes(search.toLowerCase())
  );

  const totalItems = stock.length;
  const lowStock   = stock.filter(s => parseFloat(s.quantity || 0) <= parseFloat(s.reorder_level || 0) && parseFloat(s.quantity || 0) > 0).length;
  const outOfStock = stock.filter(s => parseFloat(s.quantity || 0) <= 0).length;
  const totalValue = stock.reduce((sum, s) => sum + parseFloat(s.quantity || 0) * parseFloat(s.unit_price || 0), 0);

  return (
    <div>
      <div className="kpi-grid mb16" style={{ gridTemplateColumns: 'repeat(4,1fr)' }}>
        {[
          { label: 'Total Items',   val: totalItems,        color: 'var(--blue)',  fmt: false },
          { label: 'Low Stock',     val: lowStock,          color: 'var(--amber)', fmt: false },
          { label: 'Out of Stock',  val: outOfStock,        color: 'var(--red)',   fmt: false },
          { label: 'Total Value',   val: fmtGHS(totalValue),color: 'var(--green)', fmt: true  },
        ].map((k, i) => (
          <div key={i} className="kpi">
            <div className="kpi-label">{k.label}</div>
            <div className="kpi-val" style={{ color: k.color, fontSize: k.fmt ? 16 : 22 }}>{k.val}</div>
          </div>
        ))}
      </div>

      {lowStock > 0 && (
        <div className="alert alert-warn mb16">
          ⚠️ <strong>{lowStock} item(s)</strong> are at or below reorder level. Please replenish stock.
        </div>
      )}

      <div className="card">
        <div className="flex items-center justify-between mb16">
          <div className="card-title" style={{ margin: 0 }}>
            <span className="card-title-ic">📦</span> Stock Ledger
          </div>
          <div className="flex gap8">
            <input type="text" placeholder="Search items…" value={search} onChange={e => setSearch(e.target.value)}
              style={{ width: 220, padding: '7px 10px', fontSize: 12 }} />
            <button className="btn btn-primary btn-sm" onClick={() => setShowForm(!showForm)}>
              {showForm ? 'Cancel' : '+ Add Inventory Item'}
            </button>
          </div>
        </div>

        {showForm && (
          <div className="mb16 p16" style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 8 }}>
            <h4 style={{ margin: '0 0 12px 0' }}>Add New Inventory Item</h4>
            <form onSubmit={handleSubmit(onSubmit)}>
              <div className="fgrid">
                <div className="fg" style={{ gridColumn: 'span 2' }}>
                  <label>Item Name *</label>
                  <input type="text" placeholder="e.g. Engine Filter" {...register('name', { required: true })} />
                </div>
                <div className="fg">
                  <label>Item Type *</label>
                  <select {...register('item_type', { required: true })}>
                    <option value="SPARE_PART">Spare Part</option>
                    <option value="LUBRICANT">Lubricant</option>
                    <option value="TYRE">Tyre</option>
                    <option value="MATERIAL">Material</option>
                  </select>
                </div>
                <div className="fg">
                  <label>Unit</label>
                  <select {...register('unit')}>
                    <option value="pcs">pcs</option>
                    <option value="litres">litres</option>
                    <option value="set">set</option>
                    <option value="kg">kg</option>
                  </select>
                </div>
                <div className="fg">
                  <label>Reorder Level</label>
                  <input type="number" step="0.01" min="0" {...register('reorder_level')} />
                </div>
                <div className="fg">
                  <label>Description</label>
                  <input type="text" {...register('description')} />
                </div>
              </div>

              <div className="sec-div" style={{ marginTop: 12 }}>Opening Stock (Optional)</div>
              <div className="fgrid">
                <div className="fg">
                  <label>Location</label>
                  <select {...register('location_id')}>
                    <option value="">— Select Location —</option>
                    {locations.map(l => <option key={l.id} value={l.id}>{l.name}</option>)}
                  </select>
                </div>
                <div className="fg">
                  <label>Opening Quantity</label>
                  <input type="number" step="0.01" min="0" {...register('opening_qty')} />
                </div>
                <div className="fg">
                  <label>Unit Price (GH₵)</label>
                  <input type="number" step="0.01" min="0" {...register('unit_price')} />
                </div>
              </div>

              <div className="flex gap8 mt12">
                <button type="submit" className="btn btn-primary" disabled={saving}>
                  {saving ? '⏳ Saving…' : '✓ Save Item & Stock'}
                </button>
              </div>
            </form>
          </div>
        )}

        <div className="tbl-wrap">
          <table>
            <thead>
              <tr>
                <th>Item Code</th><th>Item Name</th><th>Category</th>
                <th>Unit</th><th>Quantity</th><th>Reorder Level</th>
                <th>Unit Price</th><th>Stock Value</th><th>Last Updated</th><th>Status</th>
              </tr>
            </thead>
            <tbody>
              {loading && (
                <tr><td colSpan={10} style={{ textAlign: 'center', padding: 32, color: 'var(--muted)' }}>Loading…</td></tr>
              )}
              {!loading && filtered.map(s => {
                const qty    = parseFloat(s.quantity || 0);
                const reorder = parseFloat(s.reorder_level || 0);
                const value  = qty * parseFloat(s.unit_price || 0);
                const isLow  = qty <= reorder && qty > 0;
                const isOut  = qty <= 0;
                return (
                  <tr key={s.id}>
                    <td className="mono" style={{ fontWeight: 600 }}>{s.item_code || '—'}</td>
                    <td style={{ fontWeight: 500 }}>{s.item_name}</td>
                    <td><span className="badge b-blue">{s.category || '—'}</span></td>
                    <td>{s.unit || '—'}</td>
                    <td style={{ fontWeight: 700, color: isOut ? 'var(--red)' : isLow ? '#b45309' : 'var(--text)' }}>
                      {qty.toLocaleString()}
                    </td>
                    <td style={{ color: 'var(--muted)' }}>{reorder.toLocaleString()}</td>
                    <td className="ced">{fmtGHS(s.unit_price)}</td>
                    <td className="ced">{fmtGHS(value)}</td>
                    <td style={{ fontSize: 11, color: 'var(--muted)' }}>{fmtDate(s.updated_at)}</td>
                    <td>
                      {isOut  && <span className="badge b-red">Out of Stock</span>}
                      {isLow  && !isOut && <span className="badge b-amber">Low Stock</span>}
                      {!isLow && !isOut && <span className="badge b-green">OK</span>}
                    </td>
                  </tr>
                );
              })}
              {!loading && filtered.length === 0 && (
                <tr><td colSpan={10} style={{ textAlign: 'center', color: 'var(--muted)', padding: 32 }}>No stock items found</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
